import json
async def main(args):
    """两份快照 diff：after 中 mtime 变化/新增 + before 中已消失（删除）。
    changed 列表按字母序（确定性输出）；files 逗号拼接供 git_commit 直接用。"""
    p = args.params
    def _load(s):
        if isinstance(s, dict):
            return s
        try:
            d = json.loads(s or "{}")
            return d if isinstance(d, dict) else {}
        except Exception:
            return {}
    before, after = _load(p.get("before")), _load(p.get("after"))
    changed = []
    for fp, mt in after.items():
        if fp not in before:
            changed.append({"file": fp, "change": "new"})
        elif abs(before[fp] - mt) > 1e-6:
            changed.append({"file": fp, "change": "modified"})
    for fp in before:
        if fp not in after:
            changed.append({"file": fp, "change": "deleted"})
    changed.sort(key=lambda x: x["file"])
    return {"files": ",".join(c["file"] for c in changed),
            "count": len(changed),
            "changed": changed}
